  live A (Z_to_bv 64 row0) = Some n0%Z -> live (c_A0 C) (Z_to_bv 64 row0) = None -> (0 <= row0 < 2 ^ 64)%Z ->
  Z_to_bv 64 sel <> Z_to_bv 64 dat ->
